// Fetch bills for selected supplier
function fetchBillsForSupplier(supplierCode) {
    console.log('Fetching bills for supplier:', supplierCode);
    fetch(`../../../../server/api/vouchers/payment_voucher/get-bills.php?supplier_code=${supplierCode}`)
        .then(response => response.json())
        .then(data => {
            console.log('Bills response:', data);
            if (data.success) {
                bills = data.data.map(bill => ({
                    number: bill.bill_no,
                    amount: bill.net_amount,
                    date: bill.purchase_date,
                    currency: bill.currency_symbol || '$'
                }));
                console.log('Bills loaded:', bills);
                setupSearchableDropdown('billNo', 'billDropdown', bills, 'display', 'number');
            }
        })
        .catch(error => console.error('Error fetching bills:', error));
}

function fetchSubAccountsForSupplier(supplierCode) {
    const apiUrl = currentPaymentType === 'customer' 
        ? `../../../../server/api/vouchers/payment_voucher/get-customer-sub-accounts.php?customer_code=${supplierCode}`
        : `../../../../server/api/vouchers/payment_voucher/get-sub-accounts.php?supplier_code=${supplierCode}`;
    
    fetch(apiUrl)
        .then(response => response.json())
        .then(data => {
            const subAccountSelect = document.getElementById('subAccount');
            subAccountSelect.innerHTML = '<option value="">Select Sub Account</option>';
            if (data.success && data.data.length > 0) {
                subAccounts = data.data;
                data.data.forEach(subAccount => {
                    const option = document.createElement('option');
                    option.value = subAccount.id;
                    option.textContent = subAccount.sub_account_name;
                    subAccountSelect.appendChild(option);
                });
            }
        })
        .catch(error => console.error('Error fetching sub-accounts:', error));
}



